dslRule:
/*!id: completion-proposal-emphasize-match-rename*/
/*!description: Rename ICompletionProposalExtension7.emphasizeMatch to getStyledDisplayString. This method was renamed in Eclipse JFace Text API. This ensures compatibility with newer versions.*/
/*!severity: WARNING*/

$proposal.emphasizeMatch($document, $offset, $stylerProvider) :: \
  instanceof($proposal, "org.eclipse.jface.text.contentassist.ICompletionProposalExtension7")
=>
$proposal.getStyledDisplayString($document, $offset, $stylerProvider)
;;

beforeExample:
package test;

import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.StyledString;
import org.eclipse.jface.text.contentassist.BoldStylerProvider;
import org.eclipse.jface.text.contentassist.ICompletionProposalExtension7;

// Mock interfaces for example compilation
interface MyIDocument extends IDocument {}
class MyBoldStylerProvider extends BoldStylerProvider {}
class MyStyledString extends StyledString {}
interface MyICompletionProposalExtension7 extends ICompletionProposalExtension7 {
    @Override
    default MyStyledString emphasizeMatch(IDocument document, int offset, BoldStylerProvider boldStylerProvider) { return new MyStyledString(); }
    @Override
    default MyStyledString getStyledDisplayString(IDocument document, int offset, BoldStylerProvider boldStylerProvider) { return new MyStyledString(); }
}

public class MyCompletionProcessor {
    public void process(MyICompletionProposalExtension7 current, IDocument document, int filterOffset, BoldStylerProvider provider) {
        // The method call to be refactored
        StyledString styledString = current.emphasizeMatch(document, filterOffset, provider);
        String displayString = styledString.getString();
        System.out.println(displayString);
    }
}

